// AuditEntries are shown only to a reader who may read the audit log; to
// anyone else the list is empty, since the trail itself does not grant it.
func (r *AIAuditEventResolver) AuditEntries(ctx context.Context, obj *aiaudit.AIAuditEvent) ([]*audit.Entry, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}
	if !r.HasPermission(ctx, authCtx, permission.ResourceAuditLog, permission.OpRead) {
		return []*audit.Entry{}, nil
	}

	entries, err := agentloaders.AuditEntriesByAIAuditEventID(ctx, obj.ID.String())
	if errors.Is(err, loadercore.ErrNotAttached) {
		return []*audit.Entry{}, nil
	}
	if err != nil {
		if errortypes.IsNotFoundError(err) {
			return []*audit.Entry{}, nil
		}

		return nil, err
	}
	if entries == nil {
		return []*audit.Entry{}, nil
	}

	return entries, nil
}

